contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v, uint topUp) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(topUp >= v, "topUp must cover v");
        require(address(this).balance >= topUp, "test contract lacks topUp");

        c.withdraw(topUp); if (__ESBMC_reverted()) return;

        uint cBalBefore = address(c).balance;
        uint callerBalBefore = address(this).balance;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint cBalAfter = address(c).balance;
        uint callerBalAfter = address(this).balance;
        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(reverted || (cBalBefore - cBalAfter == v && callerBalAfter - callerBalBefore == v && depositsAfter == depositsBefore));
    }

    receive() external payable {}
}

