pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 v, uint256 topUp) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(topUp >= v);
        vm.assume(address(this).balance >= topUp);
        try c.withdraw(topUp) {} catch { return; }
        uint cBalBefore = address(c).balance;
        uint callerBalBefore = address(this).balance;
        uint256 depositsBefore;
        try c.depositsCount() returns (uint256 __r) { depositsBefore = __r; } catch { return; }
        bool reverted;
        try c.withdraw(v) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint cBalAfter = address(c).balance;
        uint callerBalAfter = address(this).balance;
        uint256 depositsAfter;
        try c.depositsCount() returns (uint256 __r) { depositsAfter = __r; } catch { return; }
        assertTrue(reverted || (cBalBefore - cBalAfter == v && callerBalAfter - callerBalBefore == v && depositsAfter == depositsBefore));
    }

    function testFuzz_run(uint256 v, uint256 topUp) public {
        _run(v, topUp);
    }

    receive() external payable {}
}
